window.__GENWORKER_TAIL = "'use strict';\n\n// World generation core: the vanilla stage-1 generator (noise, aquifers, surface, carvers) and the\n// structures. Runs as a Web Worker; when the page cannot start workers (opened from file://, where\n// Chrome / Edge refuse them) the same core runs inside the page (see GenPool in terrain2.js).\n// Messages:\n//   {type:'init', seed, palette, smap}        -> builds the generator\n//   {type:'gen', cx, cz, dim, height, id}     -> {type:'chunk', cx, cz, id, blocks, qb, hm, sb, [meta, sx]}\n//   {type:'locate', name, cx, cz, dim, id}    -> {type:'locate', id, r}\n//   {type:'spawn', id}                        -> {type:'spawn', id, x, z}\n//   {type:'biomes', list: [[cx, cz]...], dim, id} -> {type:'biomes', id, qy, data} (3D biomes, 16 * qy a chunk)\n(function () {\n  const inWorker = typeof WorkerGlobalScope !== 'undefined' && self instanceof WorkerGlobalScope;\n  // (importScripts removed: the page passes the dependency URLs)\n  function makeGenCore() {\n    let gen = null,\n      seed = null,\n      palette = null,\n      initErr = null;\n    const gens = {};\n    // one generator per dimension; chunks are padded to the world's full height. (A generator that could not be built\n    // says why in every answer: the jobs used to fail with \"G is null\", and the page's error log never showed the cause)\n    const genFor = dim => {\n      if (!gen) throw new Error('generator not built' + (initErr ? ': ' + initErr : ''));\n      return gens[dim] || (gens[dim] = dim === 'overworld' ? gen : new WG.Generator(BigInt(seed), self.WG_DATA, palette, dim));\n    };\n    return async function handle(m, post) {\n      try {\n        if (m.type === 'init') {\n          // (again for another world - GenPool.reseed: the other dimensions' generators were the last world's)\n          for (const k in gens) delete gens[k];\n          gen = null;\n          initErr = null;\n          seed = m.seed;\n          palette = m.palette;\n          if (m.smap && self.SG) {\n            SG.setStateMap(m.smap, m.swl);\n            SG.setPalette(m.palette);\n          }\n          gen = new WG.Generator(BigInt(m.seed), self.WG_DATA, m.palette);\n          gens.overworld = gen;\n          post({\n            type: 'ready'\n          });\n        } else if (m.type === 'gen') {\n          const G = genFor(m.dim || 'overworld'),\n            t0 = performance.now();\n          // structures reaching this chunk: their terrain adaptation goes into the noise, their pieces\n          // are placed right after the carvers (vanilla places them in the feature steps)\n          // (structures that fail - their templates not unpacked, a browser without DecompressionStream - leave the chunk\n          // without them and say so in msg.warn, instead of failing the chunk. Firefox before 113 runs the game but has no\n          // DecompressionStream: SG.ready was rejected once and for all, every chunk of the session came back as an error,\n          // and the page took the errors for chunks - telemetry 11-02/03, all Firefox devices, the world never loaded)\n          let sc = null,\n            warn = null;\n          const noStructs = e => {\n            sc = null;\n            G.beard = null;\n            warn = 'structures: ' + String(e && e.stack || e);\n          };\n          if (m.structures !== false && self.SG && G.dim !== 'end') {\n            try {\n              await SG.ready;\n              sc = SG.forChunk(G, m.cx, m.cz);\n              G.beard = sc.beard;\n            } catch (e) {\n              noStructs(e);\n            }\n          }\n          const t1 = performance.now();\n          let c;\n          // (terrain that fails with a structure's adaptation in it is made again without)\n          try {\n            c = G.generate(m.cx, m.cz);\n          } catch (e) {\n            if (!G.beard) throw e;\n            noStructs(e);\n            c = G.generate(m.cx, m.cz);\n          } finally {\n            G.beard = null;\n          }\n          const t2 = performance.now();\n          let sx = null;\n          if (sc && sc.starts.length) {\n            // (pieces that fail half placed: the terrain once more, without them)\n            try {\n              sx = SG.place(G, m.cx, m.cz, c.blocks, c.meta, c.heightmap, sc.starts);\n            } catch (e) {\n              noStructs(e);\n              sx = null;\n              c = G.generate(m.cx, m.cz);\n            }\n          }\n          // surface biome per column (zoomed at the top block), for tints, weather and spawning; in the Nether\n          // there is no \"surface\", so use the floor below y 64\n          const sb = new Uint8Array(256);\n          for (let z = 0; z < 16; z++) for (let x = 0; x < 16; x++) {\n            const wx = m.cx * 16 + x,\n              wz = m.cz * 16 + z;\n            const y = G.dim === 'nether' ? 40 : c.heightmap[z * 16 + x] + 1;\n            sb[z * 16 + x] = G.biomeIdx.get(G.biomeAt(wx, y, wz));\n          }\n          if (m.height && m.height > G.height) {\n            const b = new Uint16Array(256 * m.height);\n            b.set(c.blocks);\n            c.blocks = b;\n            const mt = new Uint8Array(256 * m.height);\n            mt.set(c.meta);\n            c.meta = mt;\n            const q = new Uint8Array(16 * (m.height >> 2));\n            q.set(c.quartBiomes);\n            for (let i = c.quartBiomes.length; i < q.length; i++) q[i] = q[i - 16];\n            c.quartBiomes = q;\n          }\n          const msg = {\n            type: 'chunk',\n            cx: m.cx,\n            cz: m.cz,\n            id: m.id,\n            blocks: c.blocks,\n            qb: c.quartBiomes,\n            hm: c.heightmap,\n            sb,\n            ms: [t1 - t0, t2 - t1, performance.now() - t2]\n          };\n          if (warn) msg.warn = warn;\n          const tr = [c.blocks.buffer, c.quartBiomes.buffer, c.heightmap.buffer, sb.buffer];\n          if (sx) {\n            msg.meta = c.meta;\n            msg.sx = sx;\n            tr.push(c.meta.buffer);\n          }\n          post(msg, tr);\n        } else if (m.type === 'locate') {\n          await SG.ready;\n          post({\n            type: 'locate',\n            id: m.id,\n            r: SG.locate(genFor(m.dim || 'overworld'), m.name, m.cx, m.cz)\n          });\n        } else if (m.type === 'biomes') {\n          // vanilla's 3D biomes (one per 4 x 4 x 4 cell, indices into biome_order) of some chunks, for turning a save\n          // into a vanilla world (export.js)\n          const G = genFor(m.dim || 'overworld'),\n            QY = G.height >> 2,\n            n = 16 * QY,\n            out = new Uint8Array(m.list.length * n);\n          G.rs.endChunk();\n          m.list.forEach(([cx, cz], k) => {\n            for (let qy = 0; qy < QY; qy++) for (let qz = 0; qz < 4; qz++) for (let qx = 0; qx < 4; qx++) out[k * n + (qy * 4 + qz) * 4 + qx] = G.biomeIdx.get(G.biomes.at(cx * 4 + qx, (G.minY >> 2) + qy, cz * 4 + qz));\n          });\n          post({\n            type: 'biomes',\n            id: m.id,\n            qy: QY,\n            data: out\n          }, [out.buffer]);\n        } else if (m.type === 'spawn') {\n          const r = WG.findSpawn(genFor('overworld'));\n          post({\n            type: 'spawn',\n            id: m.id,\n            x: r[0],\n            z: r[1]\n          });\n        }\n      } catch (err) {\n        if (m.type === 'init' && !initErr) initErr = String(err && err.message || err);\n        post({\n          type: 'error',\n          id: m.id,\n          message: String(err && err.stack || err)\n        });\n      }\n    };\n  }\n  if (inWorker) {\n    const handle = makeGenCore();\n    self.onmessage = e => handle(e.data, (msg, tr) => self.postMessage(msg, tr || []));\n  } else self.makeGenCore = makeGenCore;\n})();";

window.__makeGenWorker = function () {
  if (window.__GENWORKER_URL) return window.__GENWORKER_URL;
  window.__SRC_URLS = window.__SRC_URLS || {};
  var urls = [], codes = [];
  for (var i = 0; i < ["worldgen_data.js", "blockdata.js", "modapi.js", "worldgen.js", "structures_data.js", "structgen.js", "structtypes.js", "mods/tconstruct/data.js", "mods/farmersdelight/data.js", "mods/veinminer/data.js", "mods/nightvision/data.js", "mods/dynlights/data.js", "mods/tcdemo/data.js", "mods/fddemo/data.js"].length; i++) {
    var k = ["worldgen_data.js", "blockdata.js", "modapi.js", "worldgen.js", "structures_data.js", "structgen.js", "structtypes.js", "mods/tconstruct/data.js", "mods/farmersdelight/data.js", "mods/veinminer/data.js", "mods/nightvision/data.js", "mods/dynlights/data.js", "mods/tcdemo/data.js", "mods/fddemo/data.js"][i];
    var c = window.__SRCS && (window.__SRCS[k] || window.__SRCS['js/' + k]);
    if (!c) { var f = window.__MODFILES && window.__MODFILES[k]; if (typeof f === 'string') c = f; }
    if (!c) continue;
    if (!window.__SRC_URLS[k]) window.__SRC_URLS[k] = URL.createObjectURL(new Blob([c], { type: 'text/javascript' }));
    urls.push(window.__SRC_URLS[k]); codes.push(c);
  }
  var src = codes.join('\n;\n') + ';\n' + window.__GENWORKER_TAIL;
  window.__GENWORKER_URL = URL.createObjectURL(new Blob([src], { type: 'text/javascript' }));
  return window.__GENWORKER_URL;
};
